insert into public.articles(title,body,category,kind,source_url,published) values
('Tus documentos, en un solo lugar','Antes de salir, identifica los documentos que corresponden a tu viaje. Revisa su vigencia y conserva una copia segura de las reservas y de la información que puedas necesitar.\nLos requisitos de entrada dependen del destino, la nacionalidad, el tránsito y tu situación. Confirma los requisitos aplicables con la autoridad del país de destino y tu transportador. Esta guía organiza la preparación; no determina si necesitas visa.','Documentos','guide','https://www.cancilleria.gov.co/',true),
('¿Cómo reviso el equipaje de mi viaje?','Consulta la reserva y las condiciones de la tarifa directamente con la aerolínea o el transportador. Revisa cuántas piezas puedes llevar, sus medidas y peso, y las condiciones para objetos especiales.\nSi tu itinerario combina transportadores, comprueba las condiciones de cada trayecto. Guarda la confirmación con tus documentos de viaje. No asumimos un límite de equipaje universal.','Equipaje','faq','https://www.iata.org/en/youandiata/travelers/baggage/',true),
('Organiza tu llegada antes de salir','Guarda la dirección de tu alojamiento, el punto de llegada y una forma de contactar a tu anfitrión o proveedor. Consulta opciones de transporte en los canales oficiales del aeropuerto, terminal o ciudad.\nVerifica horarios y puntos de encuentro con el proveedor elegido. Si llegas tarde o cambias de itinerario, confirma cómo afecta tu traslado.','Transporte','guide','https://www.colombia.travel/',true),
('Una lista breve para el día anterior','Revisa tus reservas, tus documentos y el estado de tus preparativos. Guarda los contactos que necesites y comparte tu itinerario con una persona de confianza si lo consideras útil.\nComprueba las indicaciones vigentes de tu transportador para llegar a tiempo. Esta lista es general: agrega los preparativos particulares que correspondan a tu viaje.','Preparación','guide','https://www.cancilleria.gov.co/',true),
('Prepara tus medios de pago','Consulta con tu entidad financiera las condiciones para utilizar tus medios de pago en el destino. Revisa comisiones, canales de soporte y procedimientos en caso de pérdida.\nUsa fuentes oficiales para consultar moneda y condiciones de cambio. No compartas claves ni códigos de autenticación en solicitudes de orientación.','Moneda','guide','https://www.banrep.gov.co/',true);
